import React, { Component } from "react";
import "./DegreeCard.css";
import { Fade } from "react-reveal";

class DegreeCard extends Component {
  render() {
    const degree = this.props.degree;
    const theme = this.props.theme;
    return (
      <div className="degree-card">
        <Fade left duration={1400} distance="24px">
          <div className="card-img" style={{ borderColor: theme.shadow }}>
            <img
              style={{
                maxWidth: `82%`,
                maxHeight: `82%`,
                objectFit: `contain`,
              }}
              src={require(`../../assests/images/${degree.logo_path}`)}
              alt={degree.alt_name}
            />
          </div>
        </Fade>
        <Fade right duration={1400} distance="28px">
          <div
            className="card-body"
            style={{
              border: `1px solid ${theme.shadow}`,
              color: theme.text,
            }}
          >
            <div className="body-header">
              <div className="body-header-title">
                <p className="degree-level">{degree.level}</p>
                <h2 className="card-title" style={{ color: theme.text }}>
                  {degree.title}
                </h2>
                <h3 className="card-subtitle" style={{ color: theme.text }}>
                  {degree.subtitle}
                </h3>
              </div>
              <div className="body-header-duration">
                <h3 className="duration ml-auto" style={{ color: theme.text }}>
                  {degree.duration}
                </h3>
                <h3 className="cgpa ml-auto">
                  {degree.resultLabel || "CGPA"} {degree.cgpa}
                </h3>
              </div>
            </div>
            {degree.tags && (
              <div className="degree-tags">
                {degree.tags.map((tag) => {
                  return <span key={tag}>{tag}</span>;
                })}
              </div>
            )}
            <div className="body-content">
              {degree.descriptions.map((sentence) => {
                return (
                  <p className="content-list" style={{ color: theme.text }} key={sentence}>
                    {sentence}
                  </p>
                );
              })}
              <a
                href={degree.website_link}
                target="_blank"
                rel="noopener noreferrer"
              >
                <div className="visit-btn">
                  <p className="btn" style={{ color: theme.text }}>
                    Visit Website
                  </p>
                </div>
              </a>
            </div>
          </div>
        </Fade>
      </div>
    );
  }
}

export default DegreeCard;
