import React, { Component } from "react";
import "./Educations.css";
import DegreeCard from "../../components/degreeCard/DegreeCard.js";
import { degrees } from "../../portfolio";
import { Fade } from "react-reveal";

class Educations extends Component {
  render() {
    const theme = this.props.theme;
    return (
      <div className="main" id="educations">
        <div className="educations-header-div">
          <Fade bottom duration={2000} distance="20px">
            <h1 className="educations-header" style={{ color: theme.text }}>
              Academic Pathway
            </h1>
            <p className="educations-subheader" style={{ color: theme.text }}>
              A practical engineering foundation, now sharpened toward battery digital twin research and doctoral study.
            </p>
          </Fade>
        </div>
        <div className="educations-body-div">
          {degrees.degrees.map((degree) => {
            return <DegreeCard degree={degree} theme={theme} key={`${degree.title}-${degree.subtitle}`} />;
          })}
        </div>
      </div>
    );
  }
}

export default Educations;
