import React from "react";
import "./Progress.css";
import { techStack } from "../../portfolio";

export default function StackProgress() {
  if (!techStack.viewSkillBars) return null;
  return (
    <section className="skills-container" aria-labelledby="capability-heading">
      <div className="skills-bar">
        <p className="skills-kicker">Evidence over percentages</p>
        <h1 className="skills-heading" id="capability-heading">Research Capabilities</h1>
        <div className="capability-grid">
          {techStack.experience.map((exp) => (
            <article className="capability-card" key={exp.Stack}>
              <span>{exp.level}</span>
              <h2>{exp.Stack}</h2>
              <p>{exp.evidence}</p>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}
