import React from "react";
import ProjectLanguages from "../../components/projectLanguages/ProjectLanguages";
import "./GithubRepoCard.css";

export default function GithubRepoCard({ repo, theme }) {
  return (
    <a
      className={`repo-card-div${repo.featured ? " is-featured" : ""}`}
      href={repo.url}
      target={repo.url.startsWith("http") && !repo.url.includes("rmpiash3.github.io") ? "_blank" : undefined}
      rel="noopener noreferrer"
      style={{ backgroundColor: theme.repobody }}
    >
      <div className="repo-card-topline">
        <span className="repo-status">{repo.status}</span>
        {repo.featured ? <span className="repo-featured">Featured research</span> : null}
      </div>
      <h2 className="repo-name" style={{ color: theme.repotext }}>{repo.name}</h2>
      <p className="repo-description" style={{ color: theme.repotext }}>{repo.description}</p>
      <dl className="repo-evidence">
        <div><dt>Role</dt><dd>{repo.role}</dd></div>
        <div><dt>Methods</dt><dd>{repo.methods}</dd></div>
        <div><dt>Outcome</dt><dd>{repo.outcome}</dd></div>
      </dl>
      <ProjectLanguages className="repo-languages" logos={repo.languages} />
    </a>
  );
}
