import React, { Component } from "react";
import "./Header.css";
import { NavLink, Link } from "react-router-dom";
import { greeting, settings } from "../../portfolio.js";

const navItems = [
  ["/home", "Home"],
  ["/research", "Research"],
  ["/projects", "Projects"],
  ["/publications", "Publications"],
  ["/experience", "Experience"],
  ["/education", "Education"],
  ["/skill", "Skills"],
  ["/contact", "Contact"],
];

class Header extends Component {
  render() {
    const theme = this.props.theme;
    const link = settings.isSplash ? "/splash" : "/home";
    return (
      <div className="header-shell">
        <header className="header">
          <NavLink to={link} tag={Link} className="logo" aria-label="RIAD MAHAMUD PIASH home">
            <img
              className="logo-avatar"
              src={require("../../assests/images/RM_PIASH.webp")}
              alt=""
            />
            <span className="logo-name" style={{ color: theme.text }}>
              {greeting.logo_name}
            </span>
          </NavLink>
          <input className="menu-btn" type="checkbox" id="menu-btn" aria-label="Toggle navigation" />
          <label className="menu-icon" htmlFor="menu-btn" aria-label="Toggle navigation menu">
            <span className="navicon"></span>
          </label>
          <nav aria-label="Primary navigation">
            <ul className="menu" style={{ backgroundColor: theme.body }}>
              {navItems.map(([path, label]) => (
                <li key={path}>
                  <NavLink
                    to={path}
                    tag={Link}
                    activeStyle={{ fontWeight: "bold" }}
                    style={{ color: theme.text }}
                  >
                    {label}
                  </NavLink>
                </li>
              ))}
            </ul>
          </nav>
        </header>
      </div>
    );
  }
}

export default Header;
